from collections import defaultdict
counter = defaultdict(int)

def solve(a):
	for ai in a:
		counter[ai] += 1
	count = list(counter.values())
	num_level = len(count)
	count.sort()
	for i in range(num_level):
		count[i] = max(count[i] - i - 2, 0)
	L = 0
	R = max(count)
	if R == 0:
		return num_level + 1

	def check(k):
		b = count.copy()
		for i in range(len(b)):
			b[i] = max(b[i] - k, 0)
		if sum(b) <= k:
			return True
		return False
	while R - L > 1:
		mid = (R + L) // 2
		if check(mid):
			R = mid
		else:
			L = mid
	return num_level + 1 + R
for a in [*open(0)][2::2]:
	counter.clear()
	res = solve(a.split())
	print(res)
